import{_ as l,C as o,o as d,c,a6 as n,E as i,j as t,a as s}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"Server-Side Template Injection","description":"Template expression evaluation, engine fingerprinting, sandbox escapes, and the path to remote code execution.","frontmatter":{"title":"Server-Side Template Injection","description":"Template expression evaluation, engine fingerprinting, sandbox escapes, and the path to remote code execution."},"headers":[],"relativePath":"ssti/index.md","filePath":"ssti/index.md"}'),p={name:"ssti/index.md"};function h(u,e,g,m,b,k){const a=o("LabGroup"),r=o("TopicComplete");return d(),c("div",null,[e[0]||(e[0]=n('<h1 id="server-side-template-injection-ssti" tabindex="-1">Server-Side Template Injection (SSTI) <a class="header-anchor" href="#server-side-template-injection-ssti" aria-label="Permalink to &quot;Server-Side Template Injection (SSTI)&quot;">​</a></h1><p class="wd-section-lede">Templates are programs. They evaluate expressions, call methods, and sometimes reach the language runtime. When user input is concatenated into a template <em>source</em> rather than passed as data, the input becomes code in the template language.</p><div class="wd-callout"><p><strong>The model.</strong> A template engine compiles a string into a render function. <code>{{ }}</code>, <code>${ }</code>, or <code>&lt;%= %&gt;</code> are expression delimiters. If the attacker controls the source, they control the expression, and the expression can often reach the host language.</p></div><h2 id="detection" tabindex="-1">Detection <a class="header-anchor" href="#detection" aria-label="Permalink to &quot;Detection&quot;">​</a></h2><p>Send a polyglot that produces a distinctive result in several engines:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>${{&lt;%[%&#39;&quot;}}%\\.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>A simpler probe is arithmetic: <code>{{7*7}}</code>, <code>${7*7}</code>, <code>&lt;%= 7*7 %&gt;</code>, <code>#{7*7}</code>. A response containing <code>49</code> where the input should be echoed is the signal.</p><table tabindex="0"><thead><tr><th>Payload</th><th>Engine family</th></tr></thead><tbody><tr><td><code>{{7*7}}</code> → 49</td><td>Jinja2, Twig, Nunjucks, Handlebars (no arithmetic by default)</td></tr><tr><td><code>${7*7}</code> → 49</td><td>FreeMarker, JSP EL, Thymeleaf, JavaScript templates</td></tr><tr><td><code>&lt;%= 7*7 %&gt;</code> → 49</td><td>ERB (Ruby), EJS</td></tr><tr><td><code>#{7*7}</code> → 49</td><td>Ruby string interpolation, some Java frameworks</td></tr><tr><td><code>{{7*&#39;7&#39;}}</code> → 7777777</td><td>Twig (string repeat) vs Jinja2 (49)</td></tr></tbody></table>',8)),i(a,{ids:"ssti-lab-server-side-template-injection-basic, ssti-lab-server-side-template-injection-basic-code-context"}),e[1]||(e[1]=n('<details class="details custom-block"><summary>🔬 Under the Hood: source context vs data context</summary><p>The safe pattern passes user input as a <strong>variable</strong>:</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_template_string(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;p&gt;Hello </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/p&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user_input)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The dangerous pattern builds the <strong>source</strong>:</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_template_string(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;p&gt;Hello &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_input </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;/p&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>In the first, <code>{{ 7*7 }}</code> in the input is data and renders literally. In the second, it is part of the template and is compiled. No amount of escaping the input helps if it is concatenated into source; the only fix is to stop concatenating.</p></details><h2 id="fingerprinting-and-documentation" tabindex="-1">Fingerprinting and documentation <a class="header-anchor" href="#fingerprinting-and-documentation" aria-label="Permalink to &quot;Fingerprinting and documentation&quot;">​</a></h2><p>Once evaluation is confirmed, identify the engine precisely. Error messages, the syntax of loops, and the available built-ins narrow it down. Public documentation then provides the path from expression to object access.</p>',3)),i(a,{ids:"ssti-lab-server-side-template-injection-using-documentation, ssti-lab-server-side-template-injection-in-an-unknown-language-with-a-documented-exploit"}),e[2]||(e[2]=n('<h2 id="reading-objects-and-files" tabindex="-1">Reading objects and files <a class="header-anchor" href="#reading-objects-and-files" aria-label="Permalink to &quot;Reading objects and files&quot;">​</a></h2><p>Most engines expose the language runtime through an object graph:</p><ul><li><strong>Jinja2:</strong> <code>{{ cycler.<strong>init</strong>.<strong>globals</strong>.os.popen(&#39;id&#39;).read() }}</code></li><li><strong>Twig:</strong> <code>{{ _self.env.registerUndefinedFilterCallback(&#39;system&#39;) }}{{ _self.env.getFilter(&#39;id&#39;) }}</code> (older versions)</li><li><strong>FreeMarker:</strong> <code>freemarker.template.utility.Execute</code> via <code>?new()</code></li><li><strong>ERB:</strong> <code>&lt;%= system(&#39;id&#39;) %&gt;</code> directly</li><li><strong>Handlebars:</strong> prototype access and helper injection</li></ul>',3)),i(a,{ids:"ssti-lab-server-side-template-injection-with-information-disclosure-via-user-supplied-objects"}),e[3]||(e[3]=t("h2",{id:"sandbox-escapes",tabindex:"-1"},[s("Sandbox escapes "),t("a",{class:"header-anchor",href:"#sandbox-escapes","aria-label":'Permalink to "Sandbox escapes"'},"​")],-1)),e[4]||(e[4]=t("p",null,[s("Sandboxed engines restrict dangerous methods, but the restrictions are often bypassable through reflection: "),t("code",null,"constructor"),s(", "),t("code",null,"__class__"),s(", "),t("code",null,"__mro__"),s(", "),t("code",null,"__subclasses__"),s(", or engine-specific escape hatches. A sandbox is not a security boundary against a language runtime unless it runs in a separate process with no capabilities.")],-1)),i(a,{ids:"ssti-lab-server-side-template-injection-in-a-sandboxed-environment"}),e[5]||(e[5]=t("h2",{id:"custom-exploits",tabindex:"-1"},[s("Custom exploits "),t("a",{class:"header-anchor",href:"#custom-exploits","aria-label":'Permalink to "Custom exploits"'},"​")],-1)),e[6]||(e[6]=t("p",null,"When the engine is known but the object graph is application-specific, the exploit is bespoke: find a class or helper that exposes file reads, command execution, or deserialization, and build the chain from the documented primitives.",-1)),i(a,{ids:"ssti-lab-server-side-template-injection-with-a-custom-exploit"}),e[7]||(e[7]=n('<details class="details custom-block"><summary>⚙️ Engine Variations: escape primitives</summary><ul><li><strong>Jinja2:</strong> <code>__globals__</code>, <code>__subclasses__</code>, <code>lipsum.__globals__[&#39;os&#39;]</code>.</li><li><strong>Twig:</strong> <code>_self.env</code>, <code>registerUndefinedFilterCallback</code>, <code>map</code>/<code>filter</code> callbacks.</li><li><strong>FreeMarker:</strong> <code>?api</code>, <code>?new()</code>, <code>Execute</code>, <code>ObjectConstructor</code>.</li><li><strong>Velocity:</strong> <code>$class.inspect()</code>, <code>$class.type</code>, <code>Runtime.exec</code>.</li><li><strong>Thymeleaf:</strong> expression preprocessing <code>__${...}__</code>, Spring bean access.</li><li><strong>Handlebars:</strong> <code>lookup</code>, <code>constructor</code>, prototype pollution.</li><li><strong>ERB/EJS:</strong> direct Ruby/JavaScript evaluation; often no sandbox at all.</li></ul><p>The engine version matters more than the engine name; patched versions remove specific primitives.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Never build template source from user input. Pass data as variables and let the engine escape it. Use logic-less templates where possible. Run rendering in a sandboxed process with no filesystem or network access. Keep engines patched. Treat template selection (user chooses a template name) as a path traversal risk too.</p></div>',2)),i(r,{"topic-id":"server-side-template-injection",label:"Mark SSTI complete"})])}const y=l(p,[["render",h]]);export{v as __pageData,y as default};
